/* ==========================================================================
   ReceiptShield — tools/bundle.js
   Regenerates two derived artifacts from the modular source, so the site can
   also be read or shipped as one file:

     receiptshield-standalone.html  the whole site, CSS + JS inlined, runnable
     SOURCE.md                      every source file concatenated in order

   Nothing here is required to run the site; it is a convenience for review.
   Run:  node tools/bundle.js
   ========================================================================== */
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');

const CSS = 'assets/css/styles.css';
const JS = [
  'assets/js/util.js',
  'assets/js/samples.js',
  'assets/js/ocr.js',
  'assets/js/parse.js',
  'assets/js/validate.js',
  'assets/js/visual.js',
  'assets/js/report.js',
  'assets/js/app.js',
];

/* ── 1. single-file runnable site ──────────────────────────── */
let html = read('index.html');

const cssTag = '<link rel="stylesheet" href="assets/css/styles.css" />';
if (!html.includes(cssTag)) throw new Error('stylesheet tag not found in index.html');
// Replacement FUNCTIONS, not strings: a string replacement would interpret
// every `$&`, `$'` and `$$` inside the inlined source as a special pattern,
// and util.js really does contain `$$`.
html = html.replace(cssTag, () => '<style>\n' + read(CSS) + '\n</style>');

JS.forEach((rel) => {
  const tag = '<script src="' + rel + '"></script>';
  if (!html.includes(tag)) throw new Error('script tag not found: ' + rel);
  html = html.replace(tag, () => '<script>\n' + read(rel).trimEnd() + '\n</script>');
});

const leftover = html.match(/(?:src|href)="assets\/[^"]*"/g);
if (leftover) {
  throw new Error('some local asset references were not inlined: ' + leftover.join(', '));
}
fs.writeFileSync(path.join(ROOT, 'receiptshield-standalone.html'), html);

/* ── 2. concatenated source listing ────────────────────────── */
const ORDER = ['index.html', CSS, ...JS, 'tools/serve.js', 'tools/bundle.js', 'package.json', 'README.md'];
const LANGS = {
  '.html': 'html', '.css': 'css', '.js': 'js', '.json': 'json', '.md': 'md',
};
const guessLang = (rel) => LANGS[path.extname(rel)] || '';

const intro =
  '# ReceiptShield — complete source listing\n\n' +
  'Generated by `node tools/bundle.js`. Every file that makes up the site,\n' +
  'in the order it is loaded. The canonical sources live in the repository;\n' +
  'this file is a reading copy.\n\n' +
  '`receiptshield-standalone.html` is the same site collapsed into one runnable file.\n\n' +
  '---\n';

const body = ORDER.map((rel) => {
  const content = read(rel).replace(/\s+$/, '');
  const lines = content.split('\n').length;
  return (
    '\n## `' + rel + '`\n\n' +
    '_' + lines + ' lines_\n\n' +
    '```' + guessLang(rel) + '\n' + content + '\n```\n'
  );
}).join('\n');

fs.writeFileSync(path.join(ROOT, 'SOURCE.md'), intro + body);

/* ── report ────────────────────────────────────────────────── */
const size = (rel) => (fs.statSync(path.join(ROOT, rel)).size / 1024).toFixed(1) + ' KB';
console.log('wrote receiptshield-standalone.html  ' + size('receiptshield-standalone.html'));
console.log('wrote SOURCE.md                      ' + size('SOURCE.md'));
JS.forEach((rel) => console.log('  inlined ' + rel + '  (' + size(rel) + ')'));
